grouped_nonkey_raw.specification:
schema_version: "1.0"
domain: TEST
keys: [ID]
input:
  SRC: {path: data.csv, types: {AGE: int, EXTRA: int}}
output:
  path: out.csv
  columns: [ID, AGE, F]
columns:
  - {name: ID, type: str}
  - {name: AGE, type: int}
  - {name: F, type: str}
rows:
  - id: emit
    dataset: SRC
    group_by: [SRC.ID]
    derivations:
      ID: SRC.ID
      AGE: {literal: 70}
      F: {flag: {condition: "SRC.EXTRA > 0", false_value: N, missing: U}}

grouped_key_raw.specification:
schema_version: "1.0"
domain: TEST
keys: [ID]
input:
  SRC: {path: data.csv, types: {AGE: int, EXTRA: int}}
output:
  path: out.csv
  columns: [ID, AGE, F]
columns:
  - {name: ID, type: str}
  - {name: AGE, type: int}
  - {name: F, type: str}
rows:
  - id: emit
    dataset: SRC
    group_by: [SRC.ID]
    derivations:
      ID: SRC.ID
      AGE: {literal: 70}
      F: {flag: {condition: "SRC.ID = 'a'", false_value: N, missing: U}}

missing_named_field_keys.specification:
schema_version: "1.0"
domain: TEST
keys: [ID]
base: SRC
input:
  SRC: {path: data.csv, types: {ID: str, K: str}}
  TAB: {path: tab.csv, types: {K: str, V: int}}
intermediates:
  - id: MATCHED
    dataset: TAB
    key: {K: KEY}
    no_match: null
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: KEY, type: str, derivation: SRC.K}
  - {name: F, type: str, derivation: {flag: {condition: "MATCHED.ABSENT > 0", false_value: N, missing: U}}}
output: {path: out.csv, columns: [ID, KEY, F]}
